export const regions=[
 {id:'iceland',name:'Исландия',stages:[stage(-100000,'Постоянное заселение Исландии относится к раннему Средневековью, прежде всего к IX веку. Для выбранной более ранней даты постоянные поселения не подтверждены.','Здесь ещё нельзя показывать скандинавские фермы или средневековые политические институты.','Сведения о местной религиозной жизни для этой даты отсутствуют.',['iceland'],'Постоянное заселение не подтверждено'),stage(800,'Исландия входит в мир североатлантических миграций. В IX веке на остров прибывают поселенцы, создающие новые хозяйства и общины.','Фермы, животноводство и морские ресурсы поддерживают жизнь поселенцев.','Скандинавские традиции и позднейшее христианство относятся к разным этапам истории острова.',['iceland'],'Период раннего заселения'),stage(1000,'Исландское общество связано с фермами, морем и североатлантическими контактами. Политические институты и внешняя власть меняются на протяжении столетий.','Сельское хозяйство, рыболовство и заморские связи остаются важными составляющими жизни.','Христианство становится важной общественной традицией; культурная память сохраняет дохристианское наследие.',['iceland'])]},
 {id:'hawaii',name:'Гавайские острова',stages:[stage(-100000,'Современные датировки относят начало полинезийского заселения Гавайев примерно к 1000–1200 годам н. э. Для выбранной ранней даты постоянные поселения не подтверждены.','Позднейшие гавайские общины и государства ещё нельзя переносить в этот период.','Местные верования для этого времени не засвидетельствованы.',['hawaii'],'Постоянное заселение не подтверждено'),stage(1000,'На Гавайи прибывают полинезийские мореходы. Первые этапы заселения датируются приблизительно 1000–1200 годами.','Мореплавание, выращивание растений и освоение местных ресурсов поддерживают новые поселения.','Полинезийские традиции предков и священных мест постепенно получают местные формы.',['hawaii'],'Период раннего заселения'),stage(1200,'На Гавайях развиваются собственные коренные общества, политические центры и способы управления ландшафтом.','Земледелие, рыболовство и обмен связывают внутренние районы с побережьем.','Коренные гавайские традиции связывают генеалогию, землю и священные места.',['hawaii']),stage(1800,'Коренное гавайское общество взаимодействует с внешней торговлей, миссиями и меняющимися государственными институтами.','Морские рынки и новые формы производства меняют труд и доступ к земле.','Коренные традиции продолжаются наряду с христианскими и другими религиями.',['hawaii'])]},
 {id:'greenland',name:'Гренландия',stages:[stage(-100000,'Раннее заселение Гренландии относится примерно к середине III тысячелетия до н. э. Для выбранной более ранней даты оно не подтверждено.','Современные ледниковые и береговые очертания не полностью совпадают с древними.','Местные верования для этой даты неизвестны.',['greenland'],'Заселение не подтверждено'),stage(-2500,'В Гренландии появляются ранние арктические общества. Культуры Саккак и Индепенденс имеют собственные ареалы и хронологии.','Охота и использование морских ресурсов поддерживают поселения; заселение разных побережий не было одновременным.','Ранние символические и ритуальные практики восстанавливаются фрагментарно.',['greenland']),stage(985,'Гренландия имеет несколько разных историй населения, включая палеоинуитские, скандинавские и позднее инуитские общества. Их нельзя свести к одной непрерывной культуре.','Морская охота, рыболовство и в скандинавских поселениях скотоводство поддерживают разные хозяйства.','Локальные арктические традиции и христианство относятся к различным сообществам и этапам.',['greenland'])]},
 {id:'svalbard',name:'Шпицберген',stages:[stage(-100000,'Для этого времени постоянное население архипелага не подтверждено. Надёжно документированные европейские плавания начинаются с экспедиции Баренца 1596 года.','Не следует автоматически переносить население соседних арктических регионов на этот архипелаг.','Верования местного постоянного населения для этой даты неизвестны.',['svalbard'],'Постоянное заселение не подтверждено'),stage(1596,'После плавания Баренца архипелаг становится пространством морских экспедиций и промысла. Позднее здесь появляются зимовки, горное дело и научные поселения.','Китобойный и другой морской промысел, затем добыча угля и исследования меняют использование островов.','Религиозные традиции связаны с участниками экспедиций и поселенцами разных стран.',['svalbard'],'Экспедиции и промысловое присутствие')]},

 {id:'antarctica',name:'Антарктида',stages:[stage(-100000,'В Антарктиде не известно коренного населения. Для этого времени нет свидетельств постоянного человеческого поселения.','Материковый ледниковый покров и океанская изоляция отличают её от заселённой Арктики.','Местная религиозная традиция населения не установлена.',['antarctica'],'Постоянное заселение не подтверждено'),stage(1820,'В XIX веке к Антарктиде начинают приходить исследовательские и промысловые экспедиции. Позднее появляются зимовки и научные станции.','Население связано с экспедициями и снабжением, а не с коренными земледельческими или охотничьими обществами.','Участники экспедиций принадлежат к разным культурным и религиозным традициям.',['antarctica'],'Экспедиционное присутствие')]},
 {id:'nz',name:'Аотеароа · Новая Зеландия',stages:[stage(-100000,'Надёжные свидетельства человеческого заселения Новой Зеландии относятся к периоду около 1250–1300 годов н. э. Для более раннего времени постоянное население не подтверждено.','Здесь ещё не следует показывать деревни маори или европейские колонии.','Религиозные практики местного населения для этого времени не засвидетельствованы.',['nz'],'Заселение не подтверждено'),stage(1250,'Начинается полинезийское заселение Аотеароа. Датировки первых прибытий находятся приблизительно между 1250 и 1300 годами.','Переселенцы прибывают на мореходных каноэ; поселения и способы использования ландшафта постепенно меняются.','Предки, генеалогия и связи с миром богов занимают важное место в полинезийских традициях.',['nz'],'Период раннего заселения'),stage(1300,'В Аотеароа складываются общества маори: родственные объединения, собственные территории и богатая устная культура.','Охота, рыболовство и выращивание культур сочетаются по-разному в зависимости от местности.','Генеалогия, почитание предков и священные места связывают общины с землёй.',['nz']),stage(1840,'Колонизация и отношения между маори и британской короной меняют распределение земли и власть. Общества маори продолжают собственную культурную и политическую жизнь.','Наряду с традиционным хозяйством расширяются рынки, переселенческие хозяйства и города.','Традиции маори сосуществуют с христианскими и другими религиозными практиками.',['nz'])]},
 {id:'australia',name:'Австралия и Тасмания',stages:[stage(-100000,'Для столь раннего времени заселение Австралии человеком пока не подтверждено. Наиболее ранние обсуждаемые археологические свидетельства относятся примерно к 65 тысячам лет назад.','Уровень моря и конфигурация побережий отличались от современных.','Для этого времени нет оснований приписывать месту конкретные верования.',['australia'],'Раннее заселение не подтверждено'),stage(-65000,'На севере Австралии известны очень ранние археологические свидетельства. Датировки и пути первоначального заселения Сахула продолжают обсуждаться.','Люди осваивают разнообразные ландшафты; нельзя переносить одну дату стоянки на весь материк.','Археология не позволяет восстановить единую систему ранних верований.',['australia'],'Раннее заселение; местная датировка неизвестна'),stage(-45000,'Австралия — мир множества коренных обществ, языков и локальных традиций. Отсутствие государства на карте не означает отсутствие людей, правил землепользования или истории.','Охота, собирательство, рыболовство, обработка растений и обмен поддерживают жизнь в очень разных природных условиях.','Земля, предки и церемонии имеют глубокое значение; практики различаются между народами и меняются во времени.',['australianLife']),stage(1788,'Британская колонизация сопровождается отчуждением земель, насилием и эпидемиями. Коренные народы сохраняют связи с землёй и продолжают бороться за права.','Колониальная экономика сосуществует с коренными способами использования ресурсов и обмена.','Традиции коренных народов продолжаются; распространяется также христианство.',['australianLife'])]},
 {id:'new-guinea',name:'Новая Гвинея',stages:[stage(-100000,'Для столь раннего времени присутствие Homo sapiens здесь не подтверждено. Позднее Новая Гвинея станет частью заселённого Сахула.','Побережья и сухопутные связи меняются вместе с уровнем моря.','Ранние верования не восстановлены.',['migration'],'Датировка местного заселения неизвестна'),stage(-45000,'В Новой Гвинее живут сообщества с разнообразными языками и способами использования лесных и горных ландшафтов.','Охота, собирательство и обработка растений предшествуют длительной истории местного земледелия.','Локальные ритуалы нельзя свести к одной религии острова.',['migration']),stage(-7000,'В высокогорьях Новой Гвинеи развиваются способы выращивания растений и управления водой. Кук сохраняет следы длительной истории земледелия.','Садоводство, дренаж и работа с влажными почвами дополняют другие источники пищи.','Ритуальная жизнь связана с локальными общинами; единой паностровной традиции нет.',['kuk'])]},
 {id:'pacific',name:'Острова Тихого океана',stages:[stage(-100000,'Заселение островов Океании происходило в разное время. Для этого раннего периода нельзя считать все острова обитаемыми.','Переходы между островами требуют отдельных морских маршрутов; современная карта не показывает древние береговые линии.','Для конкретной точки ранние обряды не установлены.',['migration'],'Заселение зависит от острова'),stage(-2000,'По островам Тихого океана распространяются мореплаватели и земледельцы. Ближняя и Дальняя Океания имеют разные хронологии заселения.','Навигация, выращивание растений, разведение животных, рыболовство и обмен соединяют островные сообщества.','Почитание предков и местные культы существуют в различных формах; единой «религии Океании» нет.',['origins'],'Заселение зависит от острова'),stage(1500,'Островные общества связаны морскими путями, но различаются политическим устройством. На одних островах власть сосредоточена у наследственных вождей, на других устроена иначе.','Море соединяет поселения; рыболовство, садоводство и обмен поддерживают островное хозяйство.','Сохраняются местные космологии и ритуалы. Распространение христианства происходит позднее и не одновременно.',['origins']),stage(1800,'Миссии, колониальные державы и торговые сети меняют жизнь островов. Местные общества продолжают собственные традиции и политические движения.','Товарное производство, морская торговля и наёмный труд дополняют местное хозяйство.','Христианские и местные традиции взаимодействуют по-разному на разных островах.',['decolon'])]},
 {id:'arctic',name:'Арктика и северная тундра',stages:[stage(-100000,'Заселение высоких широт не было одновременным. В этой точке присутствие людей для выбранной ранней даты нельзя уверенно установить.','Ледники, тундростепи и береговая линия сильно отличались от современных.','Система верований конкретного населения не восстановлена.',['migration'],'Местное заселение не установлено'),stage(-20000,'Северные сообщества приспосабливаются к холодному климату, сезонным миграциям животных и меняющемуся побережью. Некоторые территории остаются под ледником.','Охота, рыболовство и сбор ресурсов сочетаются по-разному. Морская охота становится особенно важна в ряде прибрежных обществ.','Обряды и отношения с животными известны для поздних традиций; их нельзя без доказательств переносить на ранние тысячелетия.',['america'],'Заселение неоднородно'),stage(1000,'В Арктике существуют разные сообщества морских охотников, рыболовов и охотников тундры. Территории использования ресурсов не совпадают с современными государственными границами.','Морская охота, рыболовство и охота на наземных животных обеспечивают сезонные циклы хозяйства.','Локальные духовные традиции различаются; позднее они взаимодействуют с христианскими миссиями.',['america']),stage(1800,'Колониальные администрации, торговля и миссии усиливают воздействие на северные общества. Коренные народы сохраняют собственные знания, языки и связи с землёй.','Промысловое хозяйство включается в торговые сети; позднее растут города и промышленное освоение.','Коренные и христианские традиции могут сосуществовать.',['decolon'])]},
 {id:'north-america',name:'Северная Америка',stages:[stage(-100000,'Для этой ранней даты общепринятых свидетельств заселения Америки нет. Начало и маршруты заселения продолжают обсуждаться.','Нельзя автоматически считать эту точку занятой известным позднейшим народом.','Нет оснований восстанавливать местные верования.',['america'],'Заселение не подтверждено'),stage(-30000,'Этот период относится к дискуссии о раннем заселении Америки. Разные линии археологических и генетических данных дают неодинаковые хронологии.','Речь идёт о расселении охотничьих сообществ, а не о позднейших государствах.','Конкретные религиозные системы для этой точки неизвестны.',['america'],'Ранняя хронология обсуждается'),stage(-14000,'Северная Америка заселена охотничьими и собирательскими сообществами. Разные ландшафты поддерживают разные способы жизни.','Охота, рыболовство и сбор растений сочетаются с сезонной мобильностью. Позднее в части регионов развивается земледелие.','Для ранних обществ известны отдельные погребальные и символические практики; их интерпретации неоднозначны.',['america']),stage(-1000,'На материке сосуществуют земледельцы, рыболовы, мобильные охотники и крупные поселения. Единой североамериканской культуры не существует.','Реки и дальние обменные сети связывают поселения. В ряде районов распространяется выращивание кукурузы.','Местные церемонии, священные места и устные традиции различаются между обществами.',['cahokia']),stage(1500,'Европейская колонизация приносит эпидемии, войны, торговые связи и переселения. Коренные общества сохраняют политическую и культурную самостоятельность в неодинаковой степени.','Торговля мехами, колониальное земледелие и другие рынки перестраивают обмен и землепользование.','Коренные традиции сосуществуют с христианством; обращение часто связано с колониальной властью.',['decolon'])]},
 {id:'mesoamerica',name:'Мезоамерика и Центральная Америка',stages:[stage(-100000,'Для этой ранней даты заселение региона не подтверждено. Нельзя переносить майя или ацтеков в глубокую древность.','Первые этапы присутствия людей относятся к дискуссии о заселении Америки.','Местные верования этого времени неизвестны.',['america'],'Заселение не подтверждено'),stage(-14000,'В регионе живут ранние охотничьи и собирательские сообщества. Дальнейший переход к выращиванию растений занимает тысячелетия.','Охота и сбор растений предшествуют распространению земледелия.','Полноценная реконструкция религии этих сообществ невозможна.',['america']),stage(-6000,'Выращивание растений постепенно меняет хозяйство Мезоамерики. Кукуруза со временем становится одной из важнейших культур.','Одомашнивание растений и появление деревень не происходят одновременно во всех частях региона.','Ранние ритуальные практики нельзя отождествлять с гораздо более поздними ацтекскими культами.',['meso']),stage(-1500,'В Мезоамерике развиваются крупные поселения и региональные центры. Ольмекские общества, позднее Теотиуакан, сапотекские и майяские центры имеют разные истории.','Земледелие, ремесло и обмен поддерживают города и сельские общины.','Храмы, календари и ритуалы соединяют космологию с властью; традиции различаются.',['meso']),stage(1521,'Испанское завоевание меняет власть и распределение земли. Оно не уничтожает коренные языки, общины и культурную жизнь.','Колониальные повинности и рынки сочетаются с продолжающимся общинным земледелием.','Католицизм взаимодействует с местными традициями; обращение часто сопровождается принуждением.',['decolon'])]},
 {id:'caribbean',name:'Карибские острова',stages:[stage(-100000,'Заселение островов происходило позднее и неодновременно. Для выбранной ранней даты население конкретного острова не подтверждено.','Море разделяет острова, но позднее становится средой обмена и миграций.','Местные верования для этой даты неизвестны.',['america'],'Заселение не подтверждено'),stage(-5000,'Карибские острова постепенно заселяют разные сообщества. Морские ресурсы, растения и позднее земледелие поддерживают островную жизнь.','Мореходство связывает острова с побережьем материка; конкретная дата заселения зависит от острова.','Местные обряды и представления нельзя свести к единой островной религии.',['america'],'Заселение зависит от острова'),stage(1492,'Европейская колонизация вызывает катастрофические потери коренного населения. Плантационная экономика и принудительный ввоз порабощённых африканцев глубоко меняют регион.','Плантации, атлантическая торговля и рабство определяют многие колониальные связи.','Христианские, африканские и коренные традиции взаимодействуют и преобразуются.',['decolon'])]},
 {id:'andes',name:'Анды и тихоокеанское побережье Южной Америки',stages:[stage(-100000,'Для этой ранней даты заселение Анд не подтверждено. Начало присутствия людей рассматривается в контексте заселения Америки.','Пока нельзя назвать население этой точки или его хозяйство.','Верования не восстановлены.',['america'],'Заселение не подтверждено'),stage(-14000,'Разные сообщества осваивают побережье, горные долины и высокогорья Анд.','Рыболовство, охота и сбор растений имеют разное значение на побережье и в горах.','Символические практики ранних обществ известны фрагментарно.',['america']),stage(-3000,'На побережье и в долинах возникают крупные центры, включая Караль-Супе. Это ранняя городская история, задолго до инков.','Морские ресурсы и земледелие связывают поселения разных природных зон.','Монументальные церемониальные пространства становятся важными центрами общественной жизни.',['caral']),stage(500,'В Андах существуют различные региональные общества и государства. Прибрежные и горные миры связаны обменом, но не образуют единой неизменной культуры.','Земледелие, ирригация, разведение верблюдовых и ремесло используют разнообразие высотных зон.','Культы и священные места имеют локальные и государственные формы.',['inca']),stage(1400,'В XV веке быстро расширяется Инкская держава. Её власть охватывает многие, но не все андские земли.','Дороги, трудовые повинности и перераспределение связывают области державы с местными общинами.','Государственные культы сосуществуют с почитанием местных святынь.',['inca']),stage(1532,'Испанское завоевание меняет власть, землепользование и трудовые повинности. Коренные общины продолжают жизнь в колониальном и позднейшем обществе.','Рудники, колониальные рынки и общинное земледелие создают неравные потоки труда и богатства.','Католические и андские традиции взаимодействуют, сохраняя региональные различия.',['inca','decolon'])]},
 {id:'amazon',name:'Амазония',stages:[stage(-100000,'Для этой ранней даты заселение Амазонии не подтверждено. Нельзя считать лес ни населённым конкретным поздним народом, ни доказанно пустым для всех последующих тысячелетий.','Местная археологическая хронология требует отдельных датировок.','Местные верования не восстановлены.',['america'],'Заселение не подтверждено'),stage(-14000,'Люди осваивают тропические ландшафты Южной Америки. Речные и лесные сообщества со временем вырабатывают разные способы хозяйства.','Охота, рыболовство, сбор и выращивание растений не исключают друг друга.','Ранние представления и ритуалы восстанавливаются лишь фрагментарно.',['america']),stage(-1000,'Амазония — населённый и изменяемый людьми ландшафт. В разных её частях существуют поселения, земледелие и системы управления водой и почвами.','Леса не везде являются нетронутой «дикой природой»: известны земляные сооружения, поля и преобразованные почвы.','Народы региона имеют разные языки и духовные традиции.',['amazon']),stage(1500,'Контакты, эпидемии, насилие и захват территорий резко меняют Амазонию. Отсутствие государства на карте не делает коренные земли ничейными.','Речные связи, местное хозяйство и навязанные извне товарные рынки формируют неодинаковые региональные истории.','Коренные традиции продолжаются, взаимодействуя с миссиями и другими религиями.',['amazon','decolon'])]},
 {id:'southern-america',name:'Пампа и Патагония',stages:[stage(-100000,'Для этой ранней даты население юга Южной Америки не подтверждено. Первоначальное заселение требует отдельной археологической датировки.','Современные названия народов нельзя переносить на все предшествующие эпохи.','Верования неизвестны.',['america'],'Заселение не подтверждено'),stage(-14000,'Юг Южной Америки осваивают охотничьи сообщества; прибрежные и внутренние районы имеют разные истории заселения.','Наземная охота сочетается с морским промыслом и собирательством в прибрежных районах.','Для раннего времени известны отдельные символические практики, а не единая религия региона.',['america']),stage(1500,'На юге материка продолжают жить самостоятельные коренные общества. Колониальное продвижение и позднейшее расширение государств меняют их территории.','Охота и местный обмен взаимодействуют с новыми животными, товарами и рынками.','Местные традиции сохраняются и меняются в условиях контактов и насилия.',['decolon'])]},
 {id:'nile',name:'Долина Нила и Нубия',stages:[stage(-100000,'Северо-Восточная Африка входит в длительную историю человеческого расселения. Археологические общества этого времени нельзя называть древними египтянами в позднейшем смысле.','Речные долины и соседние ландшафты поддерживают охоту, рыболовство и собирательство.','Конкретные системы ранних верований не восстановлены.',['origins']),stage(-5000,'В долине Нила развивается земледелие и растут поселения. Египет и Нубия имеют связанные, но разные истории.','Речной цикл, выращивание зерновых и обмен с соседними областями меняют хозяйство.','Местные культы и погребальные практики предшествуют позднейшим государственным религиозным системам.',['egypt']),stage(-3000,'В Египте складывается царская власть, а Нубия остаётся миром собственных обществ и политических центров.','Земледелие, ремесло, речные перевозки и дальний обмен связывают долину с окружающими регионами.','Царские и местные культы развиваются вместе с устройством общества.',['egypt']),stage(500,'Долина Нила соединяет различные государства и общины. В Нубии складываются христианские царства, а религиозная история Египта продолжает меняться.','Речное земледелие и торговля поддерживают города, монастыри и сельские поселения.','Христианство, а после VII века и ислам имеют разные региональные хронологии распространения.',['byz'])]},
 {id:'north-africa',name:'Северная Африка и Сахара',stages:[stage(-100000,'Северная Африка имеет длительную историю человеческого присутствия. Сахара не всегда выглядела как современная пустыня.','Климатические колебания меняют доступ к воде, растениям и животным.','Известны отдельные символические практики; единую раннюю религию восстановить нельзя.',['origins']),stage(-6000,'В более влажных сахаро-сахельских ландшафтах живут охотники, рыболовы и скотоводческие общества.','Распространяется содержание домашних животных; засушливость позднее меняет пути мобильности и поселения.','Наскальное искусство показывает сложный символический мир, но не даёт точной карты верований.',['pastoral']),stage(-1000,'Северная Африка связана со средиземноморскими и внутренними африканскими мирами. Местные общества не сводятся к одной внешней державе.','Земледелие, скотоводство, города, оазисы и обмен образуют различные хозяйственные зоны.','Местные, финикийские, греко-римские и позднее христианские практики имеют разные ареалы.',['rome']),stage(700,'Исламские государства и транссахарские пути соединяют города, оазисы и кочевые сообщества.','Караваны связывают Сахару с Сахелем и Средиземноморьем; местное скотоводство и земледелие продолжаются.','Ислам постепенно распространяется и взаимодействует с местными традициями.',['sahel']),stage(1800,'Европейская колониальная экспансия меняет политическую карту Северной Африки. Местные общества и религиозные институты продолжают собственную историю.','Колониальные рынки и перераспределение земли усиливают неравенство; местные сети обмена сохраняются.','Религиозная жизнь остаётся многообразной внутри преобладающих традиций.',['decolon'])]},
 {id:'west-africa',name:'Западная Африка и Сахель',stages:[stage(-100000,'Западная Африка входит в длительную историю населения Африки. Для отдельной точки нельзя восстановить непрерывную цепочку культур на сто тысяч лет.','Охота, собирательство и рыболовство зависят от лесных, речных и саванных ландшафтов.','Ранние верования не известны в виде единой системы.',['origins']),stage(-3000,'В Западной Африке развиваются местные земледельческие и скотоводческие традиции. Переходы различаются по природным зонам.','Выращивание местных растений, животноводство, рыболовство и обмен сосуществуют.','Локальные ритуальные традиции меняются вместе с обществами.',['pastoral']),stage(300,'В западном Сахеле складываются крупные политические центры. В последующие столетия здесь последовательно возвышаются Гана, Мали и Сонгай.','Транссахарские торговые связи, города и ремесло соединяют регион с другими частями Африки.','Местные традиции взаимодействуют с исламом; обращение правителей не делает население однородным.',['sahel']),stage(1500,'В Западной Африке сосуществуют государства, города и негосударственные общества. Атлантическая торговля и работорговля меняют отношения власти и обмена.','Транссахарские и атлантические пути связывают местное производство с дальними рынками, часто через насилие и принуждение.','Ислам, местные традиции и позднее христианство имеют неодинаковое распространение.',['sahel','decolon']),stage(1900,'Колониальные границы пересекают исторические пространства народов и обмена. В XX веке движения за независимость создают новые государства.','Колониальное товарное производство и города взаимодействуют с земледельческими и пастушескими хозяйствами.','Ислам, христианство и локальные традиции сосуществуют.',['decolon'])]},
 {id:'east-africa',name:'Восточная Африка',stages:[stage(-100000,'Восточная Африка — один из ключевых регионов глубокой истории человека. Общества этого времени нельзя отождествлять с современными этносами.','Охота и собирательство используют разнообразие саванн, озёр и горных ландшафтов.','Археология сохраняет фрагменты символических практик.',['origins']),stage(-4000,'В Восточной Африке сосуществуют охотничьи, рыболовные и постепенно распространяющиеся скотоводческие общества.','Животноводство не вытесняет все другие способы жизни; изменения зависят от местности.','Локальные ритуальные традиции различаются между сообществами.',['pastoral']),stage(800,'На побережье растут торговые города суахили, связанные с Индийским океаном. Внутренние области имеют собственные политические и хозяйственные истории.','Морская торговля, ремесло и местное производство связывают побережье с материком и заморскими рынками.','Ислам особенно важен для многих прибрежных центров, но не описывает автоматически весь регион.',['kilwa']),stage(1800,'Торговые и колониальные державы усиливают контроль над частями региона. Местные государства и сообщества участвуют в обмене и сопротивлении.','Плантации, караванные связи и принудительный труд меняют производство и мобильность.','Местные традиции, ислам и христианство имеют разные региональные истории.',['kilwa','decolon'])]},
 {id:'central-africa',name:'Центральная Африка',stages:[stage(-100000,'Леса и саванны Центральной Африки имеют длительную, но неравномерно изученную историю населения.','Охота, собирательство и рыболовство связаны с местными природными условиями.','Ранние системы верований не восстановлены.',['origins']),stage(-2000,'В Центральной Африке распространяются земледельческие и позднее металлообрабатывающие традиции. Лесные охотничьи сообщества продолжают жить рядом с земледельцами.','Обмен между разными хозяйственными укладами важнее картины изолированных и неизменных «племён».','Локальные традиции почитания предков и ритуальной власти различаются.',['pastoral']),stage(1400,'В разных частях Центральной Африки существуют государства и негосударственные общества. Политические центры не охватывают все формы местной власти.','Земледелие, металлургия, ремесло и торговые сети поддерживают региональные связи.','Предки, ритуальные специалисты и местные святыни играют разные роли в разных обществах.',['zimbabwe']),stage(1800,'Атлантические рынки и колониальное завоевание усиливают насилие и принуждение. История региона включает сопротивление и сохранение местных институтов.','Принудительный труд и добыча ресурсов перестраивают хозяйственные отношения.','Христианство взаимодействует с локальными религиозными традициями.',['decolon'])]},
 {id:'southern-africa',name:'Южная Африка',stages:[stage(-100000,'Южная Африка имеет глубокую историю охотничьих и собирательских обществ. Современные названия народов не следует переносить на всё это время.','Разные природные зоны поддерживают сезонную мобильность и разнообразное использование ресурсов.','Археологические свидетельства символических практик не равны точному описанию религии.',['origins']),stage(-1000,'В Южной Африке сосуществуют разные способы жизни. Распространение скотоводства, земледелия и металлургии происходит в разные сроки.','Охота и собирательство продолжаются рядом с новыми хозяйственными практиками.','Местные духовные традиции отличаются между обществами.',['pastoral']),stage(1000,'На юге Африки растут крупные центры и дальние торговые связи. Большой Зимбабве — один из примеров региональной политической и строительной истории.','Скотоводство, земледелие, ремесло и обмен связывают внутренние районы с побережьем.','Ритуальная власть и местные культы имеют разные общественные формы.',['zimbabwe']),stage(1652,'Европейские колонии и позднейшая экспансия меняют землепользование, границы и положение коренных обществ.','Захват земли, принудительный труд и колониальные рынки порождают долгосрочное неравенство.','Христианство распространяется наряду с продолжающимися местными традициями.',['decolon'])]},
 {id:'madagascar',name:'Мадагаскар',stages:[stage(-100000,'Точная хронология раннего заселения Мадагаскара обсуждается. Для столь ранней даты надёжного подтверждения населения острова нет.','Современные народы и царства острова относятся к гораздо более поздней истории.','Верования неизвестны.',['origins'],'Заселение не подтверждено'),stage(500,'История населения Мадагаскара связана с миграциями и контактами в Индийском океане. Датировки ранних этапов остаются предметом исследований.','Земледельческие и скотоводческие практики складываются из различных связей и местного опыта.','Локальные традиции почитания предков постепенно приобретают собственные региональные формы.',['origins'],'Ранняя хронология обсуждается'),stage(1500,'На острове существуют различные общества и политические центры; позднее усиливается королевство Мерина.','Земледелие, скотоводство и океанские связи поддерживают неодинаковые региональные хозяйства.','Местные традиции взаимодействуют с исламскими и христианскими контактами.',['decolon'])]},
 {id:'europe',name:'Европа',stages:[stage(-100000,'В Европе живут неандертальские сообщества. Расселение Homo sapiens относится к более позднему периоду и не происходит одновременно во всех областях.','Охота и сбор ресурсов приспосабливаются к ледниковым и межледниковым условиям.','Погребения и другие находки обсуждаются как свидетельства символического поведения.',['migration']),stage(-45000,'В Европе распространяются сообщества Homo sapiens. В разные периоды и регионы меняются каменные технологии, искусство и формы мобильности.','Охота, рыболовство и собирательство обеспечивают жизнь без обязательного земледелия или государства.','Известны символические изображения и обряды; названия божеств обычно неизвестны.',['migration']),stage(-7000,'Земледелие постепенно распространяется из юго-восточных районов Европы. Охотники и собиратели продолжают существовать и взаимодействовать с земледельцами.','Выращивание растений и содержание животных меняют поселения, питание и обмен; скорость изменений различается.','Погребальные и ритуальные традиции разнообразны и не образуют единой религии Европы.',['wheat']),stage(-800,'Европа — пространство разных обществ: городов Средиземноморья, земледельческих поселений, кельтских и других культурных миров.','Земледелие, ремесло и обмен металлами, солью и другими товарами создают дальние связи.','Местные культы, позднее греко-римские и христианские традиции меняются по регионам.',['celts','rome']),stage(500,'После распада западноримской власти возникают разные королевства, города и сельские общества. Восточная Римская империя продолжает существовать.','Земледелие остаётся основой хозяйства; торговля и ремесло связывают города и сельские земли.','Христианство распространяется неравномерно и взаимодействует с местными традициями.',['byz']),stage(1450,'Государства, города и колониальные связи перестраивают европейский мир. Разные регионы развиваются в неодинаковых политических условиях.','Расширяются дальняя торговля, товарное производство и позднее промышленность.','Католические, православные, протестантские, иудейские и мусульманские общины имеют разные истории.',['decolon']),stage(1900,'Мировые войны, государственные преобразования и миграции меняют Европу. Современные границы не совпадают с культурными и языковыми пространствами.','Индустриальное и постиндустриальное хозяйство сосуществует с региональными и международными обменами.','Существуют религиозное разнообразие и светские мировоззрения.',['decolon'])]},
 {id:'west-asia',name:'Западная Азия',stages:[stage(-100000,'Западная Азия — один из путей человеческого расселения между Африкой и Евразией. Здесь существовали разные группы древних людей.','Охота и собирательство опираются на разнообразие степей, гор и речных долин.','Ранние представления восстанавливаются лишь по отдельным находкам.',['migration']),stage(-10000,'В Передней Азии постепенно развиваются оседлые поселения, выращивание растений и содержание животных.','Переход к земледелию занимает длительное время; охота и сбор не исчезают мгновенно.','Общественные ритуальные пространства и погребальные практики показывают сложную социальную жизнь.',['wheat']),stage(-3500,'В Месопотамии растут города, храмовые хозяйства и системы учёта. Соседние горные и степные общества имеют собственные истории.','Ирригационное земледелие, ремесло и обмен поддерживают города и связывают их с источниками сырья.','Городские божества и храмовые институты играют важную роль в жизни многих центров.',['wheat']),stage(-500,'В Западной Азии сменяются крупные державы и региональные политические центры. Равнины, горы и степи сохраняют разные способы жизни.','Земледелие, города, караванные пути и скотоводство образуют взаимосвязанные хозяйства.','Иранские, месопотамские, иудейские и другие традиции сосуществуют; позднее распространяется христианство.',['sasan']),stage(650,'Исламские завоевания меняют политическую карту. Прежние языки, хозяйственные институты и религиозные общины не исчезают одномоментно.','Города, ремесло, земледелие и дальний обмен связывают регион с Африкой, Азией и Европой.','Ислам распространяется постепенно; сохраняются христианские, иудейские и другие общины.',['sasan']),stage(1900,'Распад империй, формирование государств и миграции меняют Западную Азию. Территориальные границы не описывают всё культурное разнообразие.','Города, сельское хозяйство, промышленность и мировые рынки имеют разное значение по странам.','Исламские, христианские, иудейские и другие традиции остаются внутренне разнообразными.',['decolon'])]},
 {id:'siberia',name:'Сибирь и север Евразии',stages:[stage(-100000,'Присутствие древних людей в разных частях северной Евразии имеет разные датировки. Для выбранной точки и столь ранней даты оно может быть не установлено.','Ледниковые условия, большие расстояния и сезонность ограничивают доступ к ресурсам.','Конкретные верования не восстановлены.',['migration'],'Местная датировка неизвестна'),stage(-40000,'В северной Евразии существуют мобильные охотничьи сообщества. Заселение отдельных областей и высоких широт не было одновременным.','Охота, рыболовство и сбор ресурсов сочетаются в разных природных зонах.','Для ранних обществ известны отдельные символические практики, а не единая «сибирская религия».',['migration']),stage(1000,'Сибирь населена разными охотничьими, рыболовными и скотоводческими обществами. Их языки, институты и территории использования ресурсов различаются.','Сезонный промысел, местный обмен и связи со степными и таёжными соседями поддерживают жизнь.','Локальные духовные традиции не сводятся к единой системе.',['mongol']),stage(1600,'Продвижение российского государства и сбор ясака меняют положение коренных обществ. Местные традиции, языки и хозяйство продолжаются.','Пушной промысел и торговля всё теснее связываются с внешними рынками и налоговыми обязательствами.','Местные традиции взаимодействуют с христианскими миссиями и другими религиями.',['decolon'])]},
 {id:'steppe',name:'Степи и внутренние районы Евразии',stages:[stage(-100000,'Раннее заселение внутренних районов Евразии имеет разные местные хронологии. Позднейшие кочевые народы нельзя переносить в палеолит.','Охота и собирательство связаны с подвижными ресурсами степных и горных ландшафтов.','Системы ранних верований не восстановлены.',['migration']),stage(-4000,'В степных и горных районах развиваются разные скотоводческие и земледельческие общества. Мобильность не означает отсутствие сложных правил и собственности.','Животноводство и обмен соединяют сезонные пастбища, поселения и соседние земледельческие области.','Погребальные и ритуальные традиции меняются между регионами и эпохами.',['mongol']),stage(-700,'Степная Евразия связана сетями мобильных обществ и политических объединений. Дальние контакты соединяют её с оседлыми державами.','Скотоводство, ремесло, обмен, дань и военные походы по-разному участвуют в хозяйстве.','Локальные культы, предки и позднее мировые религиозные традиции имеют разные ареалы.',['mongol']),stage(1200,'Монгольская экспансия перестраивает отношения между степью, городами и земледельческими землями. Единство империи не устраняет культурных различий.','Караванные пути, налоги, ремесло и скотоводство соединяют большие пространства.','Буддийские, мусульманские, христианские и местные традиции сосуществуют в меняющихся политических условиях.',['mongol']),stage(1700,'Степные общества взаимодействуют с расширяющимися империями и региональными государствами. Меняются границы, миграции и доступ к пастбищам.','Скотоводство, торговля и земледелие включаются в новые системы управления и рынков.','Религиозная жизнь различается между мусульманскими, буддийскими и другими сообществами.',['mongol'])]},
 {id:'south-asia',name:'Южная Азия',stages:[stage(-100000,'Ранние человеческие сообщества Южной Азии имеют длительную историю. Присутствие Homo sapiens и более ранних людей требует местных датировок.','Охота, собирательство и разнообразные ландшафты предшествуют земледельческим и городским обществам.','Ранние верования не восстановлены.',['migration']),stage(-7000,'В отдельных районах Южной Азии развиваются земледельческие поселения. Другие общества сохраняют охоту, собирательство и пастушескую мобильность.','Содержание животных, выращивание растений и обмен постепенно меняют хозяйство.','Ранние ритуальные практики нельзя автоматически называть индуизмом.',['indus']),stage(-2600,'В долине Инда и соседних областях развивается городская цивилизация Хараппы. Она не охватывает всю Южную Азию.','Города, ремесло, стандартизированные меры и обмен соединяют поселения.','Письменность Инда не прочитана; точные вероучения и имена богов не установлены.',['indus']),stage(-600,'В Южной Азии существуют различные государства и общины. Возникают и распространяются буддийские и джайнские традиции, развиваются брахманские школы.','Земледелие, города, ремесло и дальний обмен поддерживают неодинаковые политические центры.','Религиозное разнообразие не совпадает с границами одного государства.',['indus']),stage(1200,'В регионе сосуществуют султанаты, царства, города и местные общины. Их культурная жизнь связана с Индийским океаном и внутренними путями.','Сельское хозяйство, текстильное производство и обмен связывают разные природные и политические зоны.','Исламские, индуистские, буддийские, джайнские и другие традиции имеют свои истории и центры.',['indus']),stage(1750,'Колониальные компании и имперская власть усиливают контроль над многими частями Южной Азии. Местные общества участвуют в новых рынках и сопротивлении.','Налоги, сельское производство, текстиль и торговля перестраиваются в колониальных условиях.','Религиозное разнообразие сохраняется и становится частью новых политических движений.',['decolon'])]},
 {id:'east-asia',name:'Восточная Азия',stages:[stage(-100000,'В Восточной Азии существовали древние человеческие сообщества. Сроки расселения Homo sapiens различаются по местности.','Охота, собирательство и рыболовство зависят от природных зон.','Ранние верования не восстановлены.',['migration']),stage(-8000,'В разных частях Восточной Азии развиваются выращивание риса и проса, деревенская жизнь и различные неземледельческие традиции.','Не все сообщества переходят к земледелию: на Японских островах традиции Дзёмон демонстрируют сложную жизнь без обязательного зернового хозяйства.','Ритуальные предметы и погребения показывают разнообразие символических практик.',['jomon','china']),stage(-1600,'В Китае развиваются государства бронзового века, включая Шан и затем Чжоу. Другие области Восточной Азии имеют собственные истории.','Земледелие, бронзолитейное ремесло и обмен поддерживают правящие центры.','В Шан важны предки и гадательные практики; региональные традиции не одинаковы.',['china']),stage(-200,'Империи Китая сосуществуют с другими государствами и сообществами Восточной Азии. Государственные институты и письменная культура соединяют большие территории.','Земледелие, города, ремесло и сухопутные и морские пути поддерживают обмен.','Конфуцианские, даосские, буддийские и местные традиции взаимодействуют по-разному.',['han']),stage(1800,'Имперская политика, внешняя торговля и войны меняют регион. Позднее появляются новые государства и общественные движения.','Промышленность, колониальные рынки и миграции перестраивают прежние производственные связи.','Традиционные религии и новые светские мировоззрения сосуществуют.',['decolon'])]},
 {id:'southeast-asia',name:'Юго-Восточная Азия',stages:[stage(-100000,'Присутствие ранних людей в Юго-Восточной Азии не означает единовременного заселения всех островов Homo sapiens.','Изменения уровня моря соединяют и разделяют большие пространства.','Ранние системы верований не восстановлены.',['migration']),stage(-45000,'В регионе существуют охотничьи, рыболовные и собирательские сообщества. Островные и материковые области имеют разные истории.','Лесные и морские ресурсы поддерживают разнообразные способы жизни.','Локальные символические практики известны фрагментарно.',['migration']),stage(-3000,'Земледельческие и мореходные общества распространяют растения, технологии и языки. Местные охотничьи и рыболовные сообщества продолжают существовать.','Рисоводство, садоводство, рыболовство и обмен соединяют внутренние районы и побережья.','Локальные традиции предшествуют распространению индуистских, буддийских и исламских институтов.',['angkor']),stage(500,'Возникают и растут государства и городские центры, связанные с Индийским океаном и Южно-Китайским морем. Ангкор — один из позднейших крупных примеров.','Земледелие, управление водой, ремесло и морская торговля поддерживают разные политические миры.','Буддизм и индуистские традиции взаимодействуют с местными культами; позднее в ряде областей распространяется ислам.',['angkor']),stage(1600,'Колониальные компании и державы вступают в соперничество с региональными государствами. Морские торговые сети связывают местные общества с мировыми рынками.','Торговля пряностями, местное земледелие и позднее плантационное производство меняют труд и власть.','Буддизм, ислам, христианство, индуистские и местные традиции имеют разные ареалы.',['decolon'])]}
];
const byId=new Map(regions.map(r=>[r.id,r]));
export function regionAt([x,y]){if(x> -25&&x< -12&&y>63&&y<67.5)return byId.get('iceland');if(x> -161&&x< -154&&y>18&&y<23)return byId.get('hawaii');if(x>Math.max(-74,-45-(y-60)*1.8)&&x< -10&&y>=59)return byId.get('greenland');if(x>=9&&x<=36&&y>=75&&y<=82)return byId.get('svalbard');if(y< -60)return byId.get('antarctica');if((x>=165||x<=-175)&&y>=-49&&y<=-33)return byId.get('nz');if(x>=112&&x<=155&&y< -10&&y>=-45)return byId.get('australia');if(x>=130&&x<=155&&y>=-11&&y<0)return byId.get('new-guinea');if(y>=66||(x> -75&&x< -20&&y>=59))return byId.get('arctic');if((x>155||x< -140)&&y<30&&y> -60)return byId.get('pacific');if(x< -30){if(y>=7){if(x> -87&&x< -59&&y>16&&y<28)return byId.get('caribbean');return byId.get(y<32&&x> -118?'mesoamerica':'north-america');}return byId.get(x< -68?'andes':y> -18?'amazon':'southern-america');}if(x>=43&&x<=51&&y< -11&&y> -27)return byId.get('madagascar');if(x>=-20&&x<52&&y<35&&(x<34||y<12||(x<52-y*.667&&y<20))){if(x>=28&&x<38&&y>=10&&(y<23||x<34))return byId.get('nile');return byId.get(y>=20?'north-africa':y< -15?'southern-africa':x<16?'west-africa':x>=28?'east-africa':'central-africa');}if(x<40&&y>=35&&(x<29||y>=43))return byId.get('europe');if(y>=50&&x>=40)return byId.get('siberia');if(x>=40&&x<120&&y>=40)return byId.get('steppe');if(x<65)return byId.get('west-asia');if(x<92&&y<40)return byId.get('south-asia');return byId.get(y<23?'southeast-asia':'east-asia');}
export function contextAt(coords,year){const region=regionAt(coords);const s=region.stages.filter(s=>s.from<=year).at(-1)||region.stages[0];const next=region.stages[region.stages.indexOf(s)+1];return {...s,region:region.name,id:region.id,to:next?next.from-1:2025,sources:s.refs.map(id=>({title:sources[id][0],url:sources[id][1]}))};}
